ALTER TABLE "media_assets" DROP CONSTRAINT "media_assets_expiry_policy_check";--> statement-breakpoint
ALTER TABLE "media_assets" ADD CONSTRAINT "media_assets_expiry_policy_check" CHECK ("media_assets"."kind" = 'official_embed' or "media_assets"."provider_key" = 'language-reactor' or "media_assets"."provider_key" like 'supabase-storage:%' or ("media_assets"."kind" in ('audio', 'video') and "media_assets"."provider_key" = 'bunny-storage') or "media_assets"."playback_expires_at" is not null);